{"command":["bash","-lc","cat <<'EOF' > backend/src/services/themeIndex.ts
import fs from 'node:fs/promises';
import path from 'node:path';

interface ThemeMetadata {
  themeId: string;
  title: string;
  description: string;
  tags: string[];
  lastUpdated: string;
}

interface CatalogIndex {
  catalogVersion: string;
  themes: ThemeMetadata[];
}

let cachedIndex: CatalogIndex | null = null;
let lastLoaded = 0;
const FIVE_MINUTES = 5 * 60 * 1000;

export const loadStaticIndex = async (): Promise<CatalogIndex> => {
  const indexPath = path.resolve(
    process.cwd(),
    'specs/001-speckit-specify-wechat/contracts/theme-index.mock.json'
  );

  const contents = await fs.readFile(indexPath, 'utf8');
  return JSON.parse(contents) as CatalogIndex;
};

export const getCatalogIndex = async (): Promise<CatalogIndex> => {
  const now = Date.now();

  if (cachedIndex && now - lastLoaded < FIVE_MINUTES) {
    return cachedIndex;
  }

  const index = await loadStaticIndex();
  cachedIndex = index;
  lastLoaded = now;
  return index;
};

export const clearCatalogCache = () => {
  cachedIndex = null;
  lastLoaded = 0;
};
EOF
