import crypto from 'node:crypto';
import { config } from '../config';
import { getTelemetryClient } from '../telemetry/metrics';

type DeepSeekRole = 'system' | 'user' | 'assistant';

interface DeepSeekMessage {
  role: DeepSeekRole;
  content: string;
}

interface DeepSeekResponseChoice {
  message: DeepSeekMessage;
}

interface DeepSeekResponse {
  choices: DeepSeekResponseChoice[];
  usage?: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

export interface StoryTurnOptions {
  sessionId: string;
  themePrompt: string;
  history: DeepSeekMessage[];
  selectedOption?: number;
}

export interface StoryTurnResult {
  narrative: string;
  options: string[];
  ending: boolean;
  moderationMessage?: string;
}

const TELEMETRY_CLIENT = getTelemetryClient();

const isEndingFlag = (options: string[]): boolean => options.length === 0;

const sanitizeResponse = (text: string): string => text.trim();

const parseOptions = (text: string): string[] => {
  const lines = text.split('\n').map((line) => line.trim()).filter(Boolean);
  const options: string[] = [];

  for (const line of lines) {
    const match = line.match(/^\d+\.\s*(.+)$/);
    if (match) {
      options.push(match[1]);
    }
  }

  return options.slice(0, 4);
};

export const invokeDeepSeek = async (messages: DeepSeekMessage[]): Promise<DeepSeekResponse> => {
  if (!config.deepseek.apiKey) {
    throw new Error('DeepSeek API key missing');
  }

  // TODO: Replace with actual HTTP request to DeepSeek proxy API
  const demoResponse: DeepSeekResponse = {
    choices: [
      {
        message: {
          role: 'assistant',
          content: '故事继续：\n1. 继续追踪线索\n2. 与同伴讨论\n3. 查询线索\n4. 结束调查'
        }
      }
    ]
  };

  return demoResponse;
};

export const buildPrompt = (themePrompt: string, history: DeepSeekMessage[], selectedOption?: number): DeepSeekMessage[] => {
  const base: DeepSeekMessage[] = [
    { role: 'system', content: themePrompt }
  ];

  if (history.length > 0) {
    base.push(...history);
  }

  if (selectedOption !== undefined) {
    base.push({ role: 'user', content: `玩家选择了选项 ${selectedOption}` });
  }

  return base;
};

export const hashSession = (sessionId: string): string => {
  return crypto.createHash('sha256').update(sessionId).digest('hex');
};

export const generateTurn = async (options: StoryTurnOptions): Promise<StoryTurnResult> => {
  const { sessionId, themePrompt, history, selectedOption } = options;
  const start = Date.now();

  const promptMessages = buildPrompt(themePrompt, history, selectedOption);
  const response = await invokeDeepSeek(promptMessages);
  const { content } = response.choices[0].message;

  const narrative = sanitizeResponse(content);
  const optionsList = parseOptions(content);
  const ending = isEndingFlag(optionsList);

  const telemetryPayload = {
    sessionIdHash: hashSession(sessionId),
    themeId: options.history[0]?.content ?? 'unknown-theme',
    turnIndex: history.length,
    latencyMs: Date.now() - start,
    outcome: ending ? 'success' : 'success',
    timestamp: new Date().toISOString()
  };

  await TELEMETRY_CLIENT.recordTurn(telemetryPayload);

  if (ending) {
    return { narrative, options: [], ending: true };
  }

  if (optionsList.length < 4) {
    return {
      narrative,
      options: [],
      ending: true,
      moderationMessage: '生成内容缺少选项，已结束会话'
    };
  }

  return {
    narrative,
    options: optionsList,
    ending: false
  };
};
