  font-size: 28rpx;
}

.option-buttons {
  position: fixed;
  bottom: 48rpx;
  left: 0;
  width: 100%;
  background: rgba(255, 255, 255, 0.94);
  padding: 24rpx 32rpx 48rpx;
  box-sizing: border-box;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24rpx;
  box-shadow: 0 -12rpx 24rpx rgba(0, 0, 0, 0.06);
}

.option-button {
